const B64 = ``;

function decodeBase64(s) {
  const bin = atob(s);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

const WC_BYTES = 336;
const FLAG_AURORA_TICKET = 1000;
const SPECIES_DEOXYS = 410;
const SETVADDRESS = 0xb8;

function buildEmeraldWonderCard(dump) {
  const wc = new Uint8Array(WC_BYTES);
  wc.set(dump.subarray(4, 4 + 332));
  wc[0] = FLAG_AURORA_TICKET & 0xff;
  wc[1] = (FLAG_AURORA_TICKET >> 8) & 0xff;
  wc[2] = SPECIES_DEOXYS & 0xff;
  wc[3] = (SPECIES_DEOXYS >> 8) & 0xff;
  wc[4] = 2004 & 0xff;
  wc[5] = (2004 >> 8) & 0xff;
  wc[6] = 0;
  wc[7] = 0;
  return wc;
}

function buildRamScript(dump) {
  const raw = dump.subarray(WC_BYTES);
  const idx = raw.indexOf(SETVADDRESS);
  const start = idx >= 0 && idx < 16 ? idx : 0;
  return raw.subarray(start);
}

const SOURCE = decodeBase64(B64);
const WC = buildEmeraldWonderCard(SOURCE);
const SCRIPT = buildRamScript(SOURCE);

export const AURORA_TICKET_PAYLOAD = new Uint8Array(WC.length + SCRIPT.length);
AURORA_TICKET_PAYLOAD.set(WC, 0);
AURORA_TICKET_PAYLOAD.set(SCRIPT, WC.length);
export const AURORA_WONDERCARD_BYTES = AURORA_TICKET_PAYLOAD.subarray(0, WC_BYTES);
export const AURORA_SCRIPT_BYTES = AURORA_TICKET_PAYLOAD.subarray(WC_BYTES);
export const AURORA_PAYLOAD_SOURCE =
  'JPAJ USA 2004 Fall card realigned for Emerald (flag 1000, Deoxys icon, setvaddress script)';
